function topPerGroup(rows){
  // rows: [{group, id, score}]
  const byGroup = new Map();
  for (const r of rows){
    if (!byGroup.has(r.group)) byGroup.set(r.group, []);
    byGroup.get(r.group).push(r);
  }
  const out = [];
  for (const [, list] of byGroup){
    list.sort((a,b)=> b.score - a.score || a.id - b.id);
    const topScore = list[0].score;
    for (const r of list){
      // assign rank: rows tied on score share rank 1 (RANK semantics)
      const rn = r.score === topScore ? 1 : 2;
      if (rn === 1) out.push(r);
    }
  }
  return out;
}

